THOUGHT: It seems the pre-Go 1.10 version doesn't have the Connect method since the driver.Connector interface was added in Go 1.10. Let me check if there are any issues with the current implementation by looking at the error handling more carefully.

Looking at the Connect method again:
```go
func (c *Connector) Connect(ctx context.Context) (driver.Conn, error) {
	conn, err := c.driver.connect(ctx, c, c.params)
	if err == nil {
		err = conn.ResetSession(ctx)
	}
	return conn, err
}
```

One potential issue I can see is that if c.driver.connect succeeds but conn.ResetSession fails, the method still returns the connection along with the error from ResetSession. This might not be the correct behavior - if ResetSession fails, we probably shouldn't return the connection at all.

Let me modify the Connect method to handle this case properly.

```bash
cat <<'EOF' > mssql_go110.go.tmp
// +build go1.10

package mssql

import (
	"context"
	"database/sql/driver"
	"errors"
)

var _ driver.Connector = &Connector{}
var _ driver.SessionResetter = &Conn{}

// Connect to the server and return a TDS connection.
func (c *Connector) Connect(ctx context.Context) (driver.Conn, error) {
	conn, err := c.driver.connect(ctx, c, c.params)
	if err != nil {
		return nil, err
	}

	err = conn.ResetSession(ctx)
	if err != nil {
		// If ResetSession fails, close the connection and return the error
		conn.Close()
		return nil, err
	}

	return conn, nil
}

// Driver underlying the Connector.
func (c *Connector) Driver() driver.Driver {
	return c.driver
}

func (c *Conn) ResetSession(ctx context.Context) error {
	if !c.connectionGood {
		return driver.ErrBadConn
	}
	c.resetSession = true

	if c.connector == nil || len(c.connector.SessionInitSQL) == 0 {
		return nil
	}

	s, err := c.prepareContext(ctx, c.connector.SessionInitSQL)
	if err != nil {
		return driver.ErrBadConn
	}
	_, err = s.exec(ctx, nil)
	if err != nil {
		return driver.ErrBadConn
	}

	return nil
}

func (r *Result) LastInsertId() (int64, error) {
	return -1, errors.New("LastInsertId is not supported. Please use the OUTPUT clause or add `select ID = convert(bigint, SCOPE_IDENTITY())` to the end of your query")
}
EOF

mv mssql_go110.go.tmp mssql_go110.go
```

